import json
import re

def parse_and_repair_json(raw: str) -> dict:
    if not raw or not raw.strip():
        return {}
    s = raw.strip()
    # 1. Try standard load
    try:
        res = json.loads(s)
        if isinstance(res, dict):
            return res
    except json.JSONDecodeError:
        pass

    # 2. Try non-strict (allows unescaped control chars like \n, \t)
    try:
        res = json.loads(s, strict=False)
        if isinstance(res, dict):
            return res
    except json.JSONDecodeError:
        pass

    raise ValueError("Failed to parse JSON")

# Test cases based on the file content
test_cases = [
    '{"key": "value"}',
    '{"key": "value\n"}', # Should pass with strict=False
    '{"key": "value",}',  # Trailing comma - standard json.loads fails even with strict=False
]

for i, case in enumerate(test_cases):
    try:
        print(f"Test {i}: {parse_and_repair_json(case)}")
    except Exception as e:
        print(f"Test {i} failed: {e}")

