def check_git():
    try:
        branch = subprocess.check_output(['git', 'rev-parse', '--abbrev-ref', 'HEAD'], stderr=subprocess.STDOUT).decode().strip()
        status = subprocess.check_output(['git', 'status', '--porcelain'], stderr=subprocess.STDOUT).decode().strip()
        return branch, status
    except Exception as e:
        return None, str(e)

branch, status = check_git()
